CREATE TRIGGER participant_ballots_lifecycle_guard BEFORE UPDATE OF current_revision ON participant_ballots WHEN OLD.state NOT IN ('open','reopened') OR NOT EXISTS (SELECT 1 FROM events e WHERE e.id=OLD.event_id AND e.state IN ('voting','live')) BEGIN SELECT RAISE(ABORT,'voting-closed'); END;
CREATE TRIGGER ballot_versions_lifecycle_guard BEFORE INSERT ON ballot_versions WHEN NOT EXISTS (SELECT 1 FROM ballots b JOIN events e ON e.id=b.event_id AND e.community_id=b.community_id WHERE b.id=NEW.ballot_id AND b.community_id=NEW.community_id AND b.event_id=NEW.event_id AND b.state IN ('open','reopened') AND e.state IN ('voting','live')) BEGIN SELECT RAISE(ABORT,'voting-closed'); END;
